const cfg = $input.first().json;
const appKey = cfg.aliexpress_app_key;
const appSecret = cfg.aliexpress_app_secret;
const trackingId = cfg.aliexpress_tracking_id || 'default';

const ALL_KEYWORDS = [
  'LED lamp','desk lamp','ring light','night light',
  'kitchen organizer','spice rack','coffee maker',
  'wall art','decor mirror','vase decor',
  'drawer organizer','closet organizer','storage box',
  'wireless earbuds','bluetooth speaker','power bank',
  'gaming mouse','mechanical keyboard',
  'yoga mat','resistance bands',
  'makeup organizer','led mirror',
  'car phone holder','dash cam',
  'cat toy','dog leash','pet bed',
  'camping light','hiking backpack',
  'desk organizer','monitor stand'
];

const HOME_KEYWORDS = [

  'home decor','modern home decor','luxury home decor','minimalist decor',
  'interior design home','house decor ideas',

  'living room decor','modern living room decor','luxury living room decor',
  'sofa decor','decorative couch pillows','throw pillows sofa',
  'coffee table decor','centerpiece table decor',
  'tv wall decor','wall panel decor living room',
  'canvas wall art','large wall art','abstract wall art',
  'floating shelves decor','wall shelves modern',
  'ambient lighting living room','warm light living room',
  'living room rug','soft carpet','fluffy rug',
  'curtains modern','sheer curtains living room',

  'bedroom decor','modern bedroom decor','bedroom aesthetic decor',
  'bedside lamp','touch night lamp','warm bedside light',
  'bedroom lighting','soft bedroom lighting','romantic lighting',
  'bed sheets aesthetic','duvet cover modern',
  'bedroom wall decor','canvas art bedroom',
  'bedroom rug soft','fluffy carpet bedroom',

  'kitchen decor','modern kitchen decor','kitchen organizer aesthetic',
  'spice rack modern','kitchen storage containers',
  'drawer organizer kitchen','cutlery organizer',
  'kitchen shelf decor','open shelf decor kitchen',
  'countertop decor kitchen','kitchen accessories modern',

  'bathroom decor','modern bathroom decor','minimal bathroom decor',
  'soap dispenser modern','automatic soap dispenser',
  'bathroom organizer','bathroom storage solutions',
  'bathroom shelf decor','towel rack modern',
  'bathroom mirror led','bathroom accessories set',

  'home office decor','desk setup aesthetic','workspace setup',
  'desk lamp aesthetic','led desk lamp','reading lamp desk',
  'monitor stand modern','desk organization setup',
  'cable management desk','minimal desk decor',

  'kids room decor','baby room decor','nursery decor',
  'kids wall art','toy storage organizer',
  'children lighting lamp','night light kids',
  'playroom decor','kids carpet soft',

  'balcony decor','modern balcony decor','small balcony setup',
  'patio decor','garden decor ideas',
  'outdoor string lights','garden lighting solar',
  'terrace decor','outdoor furniture decor',
  'outdoor rug','balcony carpet',
  'plant pots outdoor','garden planters',

  'entryway decor','hallway decor','modern entryway',
  'shoe rack modern','entry storage bench',
  'wall hooks decor','entry mirror',
  'console table decor','hallway mirror'
];

const BATCH_SIZE = 5;

let staticData = $getWorkflowStaticData('global');
if (!staticData.cursor) staticData.cursor = 0;

function shuffle(arr){
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

const BOOST_RATIO = 0.8;
const homeCount = Math.ceil(BATCH_SIZE * BOOST_RATIO);
const otherCount = BATCH_SIZE - homeCount;

const homeKws = shuffle([...HOME_KEYWORDS]).slice(0, homeCount);
const otherKws = shuffle([...ALL_KEYWORDS]).slice(staticData.cursor, staticData.cursor + otherCount);

staticData.cursor = (staticData.cursor + otherCount) % ALL_KEYWORDS.length;

const selectedKws = [...homeKws, ...otherKws];

const pageNo = String(Math.floor(Math.random() * 5) + 1);
const SORTS = ['LAST_VOLUME_DESC','SALE_PRICE_ASC','EVALUATE_RATE_DESC'];
const sortPick = SORTS[Math.floor(Math.random()*SORTS.length)];

function formatTimestamp() {
  const now = new Date();
  const pad = n => String(n).padStart(2,'0');
  return now.getUTCFullYear()+'-'+pad(now.getUTCMonth()+1)+'-'+pad(now.getUTCDate())+' '
        +pad(now.getUTCHours())+':'+pad(now.getUTCMinutes())+':'+pad(now.getUTCSeconds());
}

function buildUrl(keyword) {
  const params = {
    app_key: appKey,
    sign_method: 'md5',
    timestamp: formatTimestamp(),
    v: '2.0',
    method: 'aliexpress.affiliate.product.query',
    keywords: keyword,
    tracking_id: trackingId,
    page_size: '50',
    page_no: pageNo,
    sort: sortPick,
    target_language: 'en',
    fields: 'product_id,product_title,target_sale_price,target_original_price,sale_price,original_price,discount,evaluate_rate,lastest_volume,promotion_link,affiliate_link,product_main_image_url',
  };

  const signString = Object.keys(params).sort().map(k => k + params[k]).join('');
  params.sign = md5(appSecret + signString + appSecret).toUpperCase();

  return 'https://api-sg.aliexpress.com/sync?' +
    Object.keys(params).map(k => encodeURIComponent(k)+'='+encodeURIComponent(params[k])).join('&');
}

console.log('Keywords:', selectedKws.join(', '));

return selectedKws.map(keyword => ({
  json: {
    api_url: buildUrl(keyword),
    keyword,
    page: pageNo
  }
}));

const allResponses = $input.all();
const allRequests  = $('Build API Request').all();

function normalizeProduct(p, keyword) {
  const price     = parseFloat(p.target_sale_price || p.target_original_price || p.sale_price || '0');
  const origPrice = parseFloat(p.target_original_price || p.original_price || '0');
  const discount  = origPrice > 0 && price > 0 && origPrice > price
    ? Math.round((1 - price / origPrice) * 100) : (p.discount ? parseInt(p.discount) : 0);
  let rawRating = parseFloat((p.evaluate_rate || '0').replace('%',''));
  const rating  = rawRating > 5 ? rawRating / 20 : rawRating;
  const orders  = parseInt(p.lastest_volume || p.total_orders || '0');
  return {
    title: (p.product_title || p.title || '').trim(),
    price, original_price: origPrice, discount, rating, orders,
    affiliate_link: (p.promotion_link || p.affiliate_link || '').trim(),
    image: (p.product_main_image_url || p.image_url || '').trim(),
    category: keyword, product_id: String(p.product_id || '')
  };
}

let allNormalized = [], apiCallCount = 0;

for (let idx = 0; idx < allResponses.length; idx++) {
  const data    = allResponses[idx].json;
  const keyword = (allRequests[idx] || allRequests[0]).json.keyword || 'unknown';
  apiCallCount++;
  if (data.error_response) {
    console.log('API error for "' + keyword + '": ' + (data.error_response.msg || 'unknown'));
    continue;
  }
  let products = [];
  try {
    const root = data.aliexpress_affiliate_product_query_response ||
                 data.aliexpress_affiliate_hotproduct_query_response || data;
    const result = (root.resp_result && root.resp_result.result) || root.result || root;
    products = (result.products && result.products.product) || [];
    if (!Array.isArray(products)) products = [products];
  } catch(e) { console.log('Parse error for "' + keyword + '": ' + e.message); continue; }
  if (!products.length) { console.log('0 products for: ' + keyword); continue; }
  const normalized = products.map(p => normalizeProduct(p, keyword)).filter(p => p.title && p.affiliate_link && p.price > 0);
  console.log('"' + keyword + '": ' + normalized.length + '/' + products.length);
  allNormalized.push(...normalized);
}

const seen = new Set();
const deduped = allNormalized.filter(p => {
  if (!p.product_id) return true;
  if (seen.has(p.product_id)) return false;
  seen.add(p.product_id); return true;
});

console.log('Pool: ' + deduped.length + ' unique products (' + apiCallCount + ' API calls)');
if (!deduped.length) return [{ json: { _flow_status: 'no_products', category: 'all' } }];
return deduped.map(p => ({ json: p }));

const all = $input.all();
const cfg = $('Config').first().json;
const minRating   = parseFloat(cfg.min_rating)   || 4.3;
const minOrders   = parseInt(cfg.min_orders)      || 200;
const minDiscount = parseInt(cfg.min_discount)    || 15;
const minPrice    = parseFloat(cfg.min_price)     || 1;
const maxPrice    = parseFloat(cfg.max_price)     || 200;
const fallbackMsg = cfg.fallback_message_no_products || 'ℹ️ לא נמצאו מוצרים מתאימים כרגע. נסה שוב בקרוב!';
const excluded = (cfg.excluded_keywords || '').split(',').map(k => k.trim().toLowerCase()).filter(Boolean);
const markers  = all.filter(i => i.json._flow_status);
const products = all.filter(i => !i.json._flow_status);
const filtered = products.filter(p => {
  const d = p.json;
  const titleLow = (d.title || '').toLowerCase();
  if (excluded.some(k => titleLow.includes(k))) return false;
  const price    = parseFloat(d.price)    || 0;
  if (price < minPrice || price > maxPrice) return false;
  const discount = parseFloat(d.discount) || 0;
  if (discount < minDiscount) return false;
  const rating   = parseFloat(d.rating)   || 0;
  if (rating > 0 && rating < minRating) return false;
  const orders   = parseInt(d.orders)     || 0;
  if (orders > 0 && orders < minOrders) return false;
  return true;
});
console.log('Filter: ' + products.length + ' in → ' + filtered.length + ' passed');
if (filtered.length === 0 && markers.length === 0) {
  return [{ json: { _flow_status: 'no_products', message_type: 'INFO', telegram_message: fallbackMsg } }];
}
return [...markers, ...filtered];

const all = $input.all();
if (all.length === 1 && all[0].json._flow_status) return all;
const cfg = $('Config').first().json;
const boostKws = (cfg.keyword_bonuses || 'wireless,smart,portable,led,usb,home,kitchen')
  .split(',').map(k => k.trim().toLowerCase()).filter(Boolean);

// Campaign category detection — registered campaigns get +30 bonus score
const CAMPAIGN_CATS = {
  home: {
    id: cfg.campaign_home_id || '9458',
    commission: 18,
    keywords: ['home','decor','lamp','light','wall','curtain','pillow','rug','shelf','mirror','vase','organizer','storage','led','bulb','room','plant','furniture','candle']
  },
  kitchen: {
    id: cfg.campaign_kitchen_id || '9460',
    commission: 14,
    keywords: ['kitchen','coffee','spice','knife','pan','pot','cook','bake','container','rack','drawer','utensil','cutting']
  },
  electronics: {
    id: cfg.campaign_electronics_id || '9456',
    commission: 18,
    keywords: ['wireless','bluetooth','usb','charger','earbuds','speaker','power bank','smart','gadget','phone','cable','headphone']
  }
};

function detectCampaign(title) {
  const t = (title || '').toLowerCase();
  for (const [cat, data] of Object.entries(CAMPAIGN_CATS)) {
    if (data.keywords.some(k => t.includes(k))) {
      return { category: cat, id: data.id, commission: data.commission };
    }
  }
  return null;
}

function scoreProduct(p) {
  const rating = p.rating || 0, orders = p.orders || 0, discount = p.discount || 0, price = p.price || 0;
  const base  = (rating * 30) + (Math.log10(orders + 1) * 25) + (discount * 2) - (price * 0.08);
  const tLow  = (p.title || '').toLowerCase();
  const boost = boostKws.some(k => tLow.includes(k)) ? 15 : 0;
  const campaign = detectCampaign(p.title);
  const campaignBonus = campaign ? 30 : 0;
  return {
    ...p,
    score: base + boost + campaignBonus,
    score_details: 'base:' + base.toFixed(1) + ' boost:' + boost + ' campaign:' + campaignBonus,
    campaign_category: campaign ? campaign.category : null,
    campaign_activity_id: campaign ? campaign.id : null,
    campaign_commission: campaign ? campaign.commission : null
  };
}

const scored = all.map(item => item.json).map(scoreProduct).sort((a, b) => b.score - a.score);
console.log('Scored', scored.length, 'products. Top:', scored[0] ? scored[0].score.toFixed(1) + ' (' + scored[0].title.slice(0,40) + ') campaign:' + (scored[0].campaign_category || 'none') : 'none');
return scored.map(p => ({ json: p }));

const staticData = $getWorkflowStaticData('global'); if (!staticData.posted) staticData.posted = {};
const all = $input.all();
const cfg = $('Config').first().json;
const n = Math.max(1, parseInt(cfg.products_per_run) || 1);
const fallbackMsg = cfg.fallback_message_no_products || 'ℹ️ לא נמצאו מוצרים מתאימים כרגע.';
const products = all.map(i => i.json);

if (products.length === 1 && products[0]._flow_status) {
  if (products[0]._flow_status === 'api_error') return [{ json: { message_type: 'ERROR', telegram_message: '❌ שגיאה בשליפת מוצרים' } }];
  return [{ json: { message_type: 'INFO', telegram_message: fallbackMsg } }];
}
if (!products.length) return [{ json: { message_type: 'INFO', telegram_message: fallbackMsg } }];

function cleanTitle(t) {
  t = (t || '').replace(/[\u4e00-\u9fff\u3400-\u4dbf]+/g, '');
  t = t.replace(/\b(NEW|HOT|SALE|BEST|TOP|ORIGINAL)\b\s*/gi, '');
  t = t.replace(/\b20[2-3][0-9]\b\s*/g, '');
  t = t.replace(/\s{2,}/g, ' ').trim();
  return t.replace(/^[\s,\-]+|[\s,\-]+$/g, '');
}

// Extract significant words (>3 chars, not common filler)
const STOP_WORDS = new Set(['with','from','that','this','have','for','are','but','not','you','all','can','her','was','one','our','out','day','get','has','him','his','how','its','may','who','did','let','put','say','she','too','use','way','and','the','for','ing','per','pcs','set','bag','box','case','type','size','new','hot','1pc','2pc','3pc']);

function titleWords(t) {
  return (t || '').toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/)
    .filter(w => w.length > 3 && !STOP_WORDS.has(w));
}

function isTooSimilar(titleA, titleB) {
  const wordsA = new Set(titleWords(titleA));
  const wordsB = titleWords(titleB);
  const common = wordsB.filter(w => wordsA.has(w));
  // Similar if 3+ meaningful words in common
  return common.length >= 3;
}

// Shuffle top candidates so we don't always pick the same bestsellers
const POOL = Math.min(50, products.length);
const pool = products.slice(0, POOL);
for (let i = pool.length - 1; i > 0; i--) {
  const j = Math.floor(Math.random() * (i + 1));
  [pool[i], pool[j]] = [pool[j], pool[i]];
}
const shuffled = [...pool, ...products.slice(POOL)];

const selected = [];
const selectedTitles = [];

for (const p of shuffled) {
  if (staticData.posted[p.product_id]) continue;
  if (selected.length >= n) break;
  const isDuplicate = selectedTitles.some(t => isTooSimilar(t, p.title));
  if (!isDuplicate) {
    selected.push(p);
    staticData.posted[p.product_id] = Date.now();
    selectedTitles.push(p.title);
  }
}

// If not enough unique products, fill from remaining (allow less strict)
if (selected.length < n) {
  for (const p of products) {
    if (selected.length >= n) break;
    if (!selected.includes(p)) selected.push(p);
    staticData.posted[p.product_id] = Date.now();
  }
}

console.log('Selected ' + selected.length + ' unique products from ' + products.length + ' candidates');

const result = selected.map(p => ({
  json: { ...p, message_type: 'PRODUCT', cleaned_title: cleanTitle(p.title), total_candidates: products.length }
}));

if (selected.length < n) {
  result.push({ json: { message_type: 'INFO', telegram_message: 'ℹ️ נמצאו ' + selected.length + ' מוצרים מתוך ' + n + ' שביקשת.' } });
}

return result;

const all = $input.all();

const kwBenefits = {
  'wireless':'אלחוטי ונוח לשימוש','bluetooth':'חיבור Bluetooth מהיר ויציב','wifi':'חיבור WiFi מובנה',
  'type-c':'טעינה מהירה דרך Type-C','usb':'חיבור USB נוח','led':'תאורת LED חזקה וחסכונית',
  'rgb':'תאורת RGB צבעונית','waterproof':'עמיד למים ושפיכות','stainless':'חומר איכותי ועמיד',
  'silicone':'עשוי סיליקון רך ונעים','portable':'קל וקומפקטי – נוח לקחת לכל מקום',
