const all = $input.all();
const origItems = $('Apply Short Link').all();

return all.map((item, idx) => {
  const origItem = origItems[idx] || { json: {} };
  const orig = origItem.json;

  // INFO/ERROR items — return unchanged
  if (orig.message_type === 'INFO' || orig.message_type === 'ERROR') {
    return origItem;
  }

  // Extract AI-generated message from <AD> section
  let aiMessage = null;
  try {
    const raw = item.json && item.json.choices && item.json.choices[0] &&
                item.json.choices[0].message && item.json.choices[0].message.content;
    if (raw && typeof raw === 'string') {
      // Try to extract <AD> section
      const adMatch = raw.match(/<AD>([\s\S]*?)<\/AD>/i);
      if (adMatch && adMatch[1].trim().length > 20) {
        aiMessage = adMatch[1].trim();
      } else if (raw.trim().length > 20) {
        // Fallback: use full content if no tags found
        aiMessage = raw.trim();
      }
    }
  } catch(e) {
    console.log('Parse Groq error:', e.message);
  }

  if (aiMessage) {
    console.log('Groq AI enhanced post for:', orig.title || 'unknown');
  } else {
    console.log('Groq fallback to original post for:', orig.title || 'unknown');
  }

  return {
    json: Object.assign({}, orig, {
      telegram_message: aiMessage || orig.telegram_message || ''
    })
  };
});

