}

function buildUrl(keyword) {
  const params = {
    app_key: appKey,
    sign_method: 'md5',
    timestamp: formatTimestamp(),
    v: '2.0',
    method: 'aliexpress.affiliate.product.query',
    keywords: keyword,
    tracking_id: trackingId,
    page_size: '50',
    page_no: pageNo,
    sort: sortPick,
    target_language: 'en',
    fields: 'product_id,product_title,target_sale_price,target_original_price,sale_price,original_price,discount,evaluate_rate,lastest_volume,promotion_link,affiliate_link,product_main_image_url',
  };

  const signString = Object.keys(params).sort().map(k => k + params[k]).join('');
  params.sign = md5(appSecret + signString + appSecret).toUpperCase();

  return 'https://api-sg.aliexpress.com/sync?' +
    Object.keys(params).map(k => encodeURIComponent(k)+'='+encodeURIComponent(params[k])).join('&');
}

