function cleanTitle(t) {
  t = (t || '').replace(/[\u4e00-\u9fff\u3400-\u4dbf]+/g, '');
  t = t.replace(/\b(NEW|HOT|SALE|BEST|TOP|ORIGINAL)\b\s*/gi, '');
  t = t.replace(/\b20[2-3][0-9]\b\s*/g, '');
  t = t.replace(/\s{2,}/g, ' ').trim();
  return t.replace(/^[\s,\-]+|[\s,\-]+$/g, '');
}

// Extract significant words (>3 chars, not common filler)
const STOP_WORDS = new Set(['with','from','that','this','have','for','are','but','not','you','all','can','her','was','one','our','out','day','get','has','him','his','how','its','may','who','did','let','put','say','she','too','use','way','and','the','for','ing','per','pcs','set','bag','box','case','type','size','new','hot','1pc','2pc','3pc']);

function titleWords(t) {
  return (t || '').toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/)
    .filter(w => w.length > 3 && !STOP_WORDS.has(w));
}

function isTooSimilar(titleA, titleB) {
  const wordsA = new Set(titleWords(titleA));
  const wordsB = titleWords(titleB);
  const common = wordsB.filter(w => wordsA.has(w));
  // Similar if 3+ meaningful words in common
  return common.length >= 3;
}

// Shuffle top candidates so we don't always pick the same bestsellers
const POOL = Math.min(50, products.length);
const pool = products.slice(0, POOL);
for (let i = pool.length - 1; i > 0; i--) {
  const j = Math.floor(Math.random() * (i + 1));
  [pool[i], pool[j]] = [pool[j], pool[i]];
}
const shuffled = [...pool, ...products.slice(POOL)];

const selected = [];
const selectedTitles = [];

for (const p of shuffled) {
  if (staticData.posted[p.product_id]) continue;
  if (selected.length >= n) break;
  const isDuplicate = selectedTitles.some(t => isTooSimilar(t, p.title));
  if (!isDuplicate) {
    selected.push(p);
    staticData.posted[p.product_id] = Date.now();
    selectedTitles.push(p.title);
  }
}

// If not enough unique products, fill from remaining (allow less strict)
if (selected.length < n) {
  for (const p of products) {
    if (selected.length >= n) break;
    if (!selected.includes(p)) selected.push(p);
    staticData.posted[p.product_id] = Date.now();
  }
}

