  return [{ json: { _flow_status: 'no_products', category } }];
}

const normalized = products.map(p => {
  const price     = parseFloat(p.target_sale_price || p.target_original_price || p.sale_price || '0');
  const origPrice = parseFloat(p.target_original_price || p.original_price || '0');
  const discount  = origPrice > 0 && price > 0 && origPrice > price
    ? Math.round((1 - price / origPrice) * 100) : (p.discount ? parseInt(p.discount) : 0);
  let rawRating = parseFloat((p.evaluate_rate || '0').replace('%',''));
  const rating  = rawRating > 5 ? rawRating / 20 : rawRating;
  const orders  = parseInt(p.lastest_volume || p.total_orders || '0');
  return {
    title:         (p.product_title || p.title || '').trim(),
    price,
    original_price: origPrice,
    discount,
    rating,
    orders,
    affiliate_link: (p.promotion_link || p.affiliate_link || '').trim(),
