const all = $input.all();
const cfg = $('Config').first().json;

// All thresholds from Config — single source of truth
const minRating   = parseFloat(cfg.min_rating)   || 4.3;
const minOrders   = parseInt(cfg.min_orders)      || 200;
const minDiscount = parseInt(cfg.min_discount)    || 15;
const minPrice    = parseFloat(cfg.min_price)     || 1;
const maxPrice    = parseFloat(cfg.max_price)     || 200;
const fallbackMsg = cfg.fallback_message_no_products || 'ℹ️ לא נמצאו מוצרים מתאימים כרגע. נסה שוב בקרוב!';

const excluded = (cfg.excluded_keywords || '').split(',').map(k => k.trim().toLowerCase()).filter(Boolean);

// Pass through flow markers unchanged
const markers = all.filter(i => i.json._flow_status);
const products = all.filter(i => !i.json._flow_status);

const filtered = products.filter(p => {
  const d = p.json;

  // Excluded keywords
  const titleLow = (d.title || '').toLowerCase();
  if (excluded.some(k => titleLow.includes(k))) return false;

  // Price must be in range
  const price = parseFloat(d.price) || 0;
  if (price < minPrice || price > maxPrice) return false;

  // Discount must meet threshold
  const discount = parseFloat(d.discount) || 0;
  if (discount < minDiscount) return false;

  // Rating: only reject if data is present AND below threshold
  // rating=0 means API didn’t return it — allow through
  const rating = parseFloat(d.rating) || 0;
  if (rating > 0 && rating < minRating) return false;

  // Orders: only reject if data is present AND below threshold
  // orders=0 means API didn’t return lastest_volume — allow through
  const orders = parseInt(d.orders) || 0;
  if (orders > 0 && orders < minOrders) return false;

  return true;
});

console.log('Filter: ' + products.length + ' in → ' + filtered.length + ' passed');

if (filtered.length === 0 && markers.length === 0) {
  return [{ json: {
    _flow_status: 'no_products',
    message_type: 'INFO',
    telegram_message: fallbackMsg
  }}];
}

return [...markers, ...filtered];

// Pass through flow-status markers
const all = $input.all();
if (all.length === 1 && all[0].json._flow_status) return all;

const cfg = $('Config').first().json;

// Read keyword_bonuses from Config — single source of truth
const boostKws = (cfg.keyword_bonuses || 'wireless,smart,portable,led,usb,car,tool,home,kitchen')
  .split(',').map(k => k.trim().toLowerCase()).filter(Boolean);

function scoreProduct(p) {
  const rating   = p.rating   || 0;
  const orders   = p.orders   || 0;
  const discount = p.discount || 0;
  const price    = p.price    || 0;

  // Base formula: quality + popularity (log scale) + discount - price penalty
  const base  = (rating * 30) + (Math.log10(orders + 1) * 25) + (discount * 2) - (price * 0.08);
  const tLow  = (p.title || '').toLowerCase();
  const boost = boostKws.some(k => tLow.includes(k)) ? 15 : 0;
  const score = base + boost;

  return { ...p, score, score_details: 'base:' + base.toFixed(1) + ' boost:' + boost };
}

const scored = all.map(item => item.json).map(scoreProduct).sort((a, b) => b.score - a.score);
console.log('Scored', scored.length, 'products. Top:', scored[0] ? scored[0].score.toFixed(1) + ' (' + scored[0].title.slice(0,40) + ')' : 'none');
return scored.map(p => ({ json: p }));

