const products = all.map(i => i.json);

if (products.length === 1 && products[0]._flow_status) {
  const status = products[0]._flow_status;
  if (status === 'api_error') {
    return [{ json: { message_type: 'ERROR', telegram_message: '❌ שגיאה בשליפת מוצרים מ-AliExpress\nקוד: ' + (products[0]._error_code || 'unknown') }}];
  }
  return [{ json: { message_type: 'INFO', telegram_message: fallbackMsg }}];
}

if (!products.length) {
  return [{ json: { message_type: 'INFO', telegram_message: fallbackMsg }}];
}

function cleanTitle(t) {
  t = t.replace(/[\u4e00-\u9fff\u3400-\u4dbf]+/g, '');
  t = t.replace(/\b(NEW|HOT|SALE|BEST|TOP|ORIGINAL)\b\s*/gi, '');
  t = t.replace(/\b20[2-3][0-9]\b\s*/g, '');
  t = t.replace(/【[^】]*】/g, '');
  t = t.replace(/\s{2,}/g, ' ').trim();
  return t.replace(/^[\s,\-]+|[\s,\-]+$/g, '');
}

const selected = products.slice(0, Math.min(n, products.length));
console.log('Returning ' + selected.length + ' product(s) from ' + products.length + ' candidates (products_per_run=' + n + ')');

const result = selected.map(p => ({ json: { ...p, message_type: 'PRODUCT', cleaned_title: cleanTitle(p.title), total_candidates: products.length } }));

// Notify if fewer products than requested
if (selected.length < n) {
  result.push({ json: {
    message_type: 'INFO',
    telegram_message: 'ℹ️ נמצאו ' + selected.length + ' מוצרים מתוך ' + n + ' שביקשת — הפילטר הצר את התוצאות.'
  }});
}

return result;

