function getBenefits(product) {
  const tLow = (product.title || '').toLowerCase();
  const benefits = [];
  const used = new Set();
  for (const [kw, ben] of Object.entries(kwBenefits)) {
    if (tLow.includes(kw) && !used.has(ben)) { benefits.push(ben); used.add(ben); if (benefits.length >= 5) break; }
  }
  if (benefits.length < 3) {
    const disc = product.discount || 0, orders = product.orders || 0, rating = product.rating || 0;
    if (disc >= 50 && !used.has('bd')) { benefits.push('הנחה מעל 50% — מחיר שאי אפשר לפספס'); used.add('bd'); }
    else if (disc >= 30 && !used.has('d')) { benefits.push('מחיר מציאה שלא תמיד רואים'); used.add('d'); }
    if (orders >= 10000 && !used.has('oh')) { benefits.push('יותר מ-10,000 לקוחות מרוצים'); used.add('oh'); }
    else if (orders >= 1000 && !used.has('om')) { benefits.push('אלפי לקוחות קנו ומרוצים'); used.add('om'); }
    if (rating >= 4.8 && !used.has('r')) { benefits.push('דירוג 4.8+ על ידי קונים אמיתיים'); used.add('r'); }
    else if (rating >= 4.5 && !used.has('r')) { benefits.push('דירוג 4.5+ על ידי קונים אמיתיים'); used.add('r'); }
    if (!used.has('s')) { benefits.push('משלוח עם AliExpress Buyer Protection'); used.add('s'); }
