  if (p.message_type === 'INFO' || p.message_type === 'ERROR' || p._flow_status) {
    return { json: { ...p, _skip_link: true, link_api_url: 'https://api-sg.aliexpress.com/sync' } };
  }
  const productId = p.product_id || '';
  if (!productId) {
    console.log('No product_id, skipping short link generation');
    return { json: { ...p, _skip_link: true, link_api_url: 'https://api-sg.aliexpress.com/sync' } };
  }
  console.log('Building short link request for product:', productId);
  return { json: { ...p, _skip_link: false, link_api_url: buildShortLinkUrl(productId) } };
})

