const cfg = $input.first().json;
const appKey = cfg.aliexpress_app_key;
const appSecret = cfg.aliexpress_app_secret;
const trackingId = cfg.aliexpress_tracking_id || 'default';

const kwList = (cfg.keyword_bonuses || 'wireless,smart,portable,LED,USB,car,tool,home,kitchen')
  .split(',').map(k => k.trim()).filter(Boolean);

const nowMin = Math.floor(Date.now() / 60000);
const keyword = kwList[nowMin % kwList.length];
const pageNo = String((Math.floor(nowMin / kwList.length) % 5) + 1);

function formatTimestamp() {
  const now = new Date();
  const pad = n => String(n).padStart(2,'0');
  return now.getUTCFullYear()+'-'+pad(now.getUTCMonth()+1)+'-'+pad(now.getUTCDate())+' '
        +pad(now.getUTCHours())+':'+pad(now.getUTCMinutes())+':'+pad(now.getUTCSeconds());
}

const params = {
  app_key: appKey, sign_method: 'md5', timestamp: formatTimestamp(), v: '2.0',
  method: 'aliexpress.affiliate.product.query',
  keywords: keyword, tracking_id: trackingId,
  page_size: '50', page_no: pageNo,
  sort: 'LAST_VOLUME_DESC', target_language: 'en',
  fields: 'product_id,product_title,target_sale_price,target_original_price,sale_price,original_price,discount,evaluate_rate,lastest_volume,promotion_link,affiliate_link,product_main_image_url',
};

const signString = Object.keys(params).sort().map(k => k + params[k]).join('');
params.sign = md5(appSecret + signString + appSecret).toUpperCase();

const url = 'https://api-sg.aliexpress.com/sync?' +
  Object.keys(params).map(k => encodeURIComponent(k)+'='+encodeURIComponent(params[k])).join('&');

return [{ json: { api_url: url, keyword, page: pageNo } }];

const data = $input.first().json;
const category = $('Build API Request').first().json.keyword || 'unknown';

if (data.error_response) {
  const errCode = String(data.error_response.code || 'unknown');
  const errMsg = String(data.error_response.msg || 'API error');
  return [{ json: { _flow_status: 'api_error', _error_code: errCode, _error_msg: errMsg, category } }];
}

let products = [];
try {
  const root = data.aliexpress_affiliate_product_query_response || data;
  const result = (root.resp_result && root.resp_result.result) || root.result || root;
  products = (result.products && result.products.product) || [];
  if (!Array.isArray(products)) products = [products];
} catch(e) {
  return [{ json: { _flow_status: 'no_products', category } }];
}

if (!products.length) return [{ json: { _flow_status: 'no_products', category } }];

const normalized = products.map(p => {
  const price = parseFloat(p.target_sale_price || p.sale_price || '0');
  const origPrice = parseFloat(p.target_original_price || p.original_price || '0');
  const discount = origPrice > 0 && price > 0 && origPrice > price ? Math.round((1 - price/origPrice)*100) : (parseInt(p.discount)||0);
  let rawRating = parseFloat((p.evaluate_rate||'0').replace('%',''));
  const rating = rawRating > 5 ? rawRating/20 : rawRating;
  const orders = parseInt(p.lastest_volume||'0');
  return {
    title: (p.product_title||'').trim(),
    price, original_price: origPrice, discount, rating, orders,
    affiliate_link: (p.promotion_link||p.affiliate_link||'').trim(),
    image: (p.product_main_image_url||'').trim(),
    category, product_id: String(p.product_id||'')
  };
}).filter(p => p.title && p.affiliate_link && p.price > 0);

if (!normalized.length) return [{ json: { _flow_status: 'no_products', category } }];

return normalized.map(p => ({ json: p }));

