function scoreProduct(p) {
  const base = (p.rating*30)+(Math.log10(p.orders+1)*25)+(p.discount*2)-(p.price*0.08);
  const boost = boostKws.some(k=>(p.title||'').toLowerCase().includes(k))?15:0;
  return {...p, score: base+boost, score_details:'base:'+base.toFixed(1)+' boost:'+boost};
}

const scored = all.map(i=>i.json).map(scoreProduct).sort((a,b)=>b.score-a.score);
return scored.map(p=>({json:p}));

