function formatTimestamp(){
  const now=new Date(),pad=n=>String(n).padStart(2,'0');
  return now.getUTCFullYear()+'-'+pad(now.getUTCMonth()+1)+'-'+pad(now.getUTCDate())+' '+pad(now.getUTCHours())+':'+pad(now.getUTCMinutes())+':'+pad(now.getUTCSeconds());
}

function buildShortLinkUrl(productId){
  const sourceValue='https://www.aliexpress.com/item/'+productId+'.html';
  const params={app_key:appKey,sign_method:'md5',timestamp:formatTimestamp(),v:'2.0',method:'aliexpress.affiliate.link.generate',source_values:sourceValue,promotion_link_type:'0',tracking_id:trackingId};
  const signString=Object.keys(params).sort().map(k=>k+params[k]).join('');
  params.sign=md5(appSecret+signString+appSecret).toUpperCase();
  return 'https://api-sg.aliexpress.com/sync?'+Object.keys(params).map(k=>encodeURIComponent(k)+'='+encodeURIComponent(params[k])).join('&');
}

return all.map(item=>{
  const p=item.json;
  if(p.message_type==='INFO'||p.message_type==='ERROR'||p._flow_status){
    return {json:{...p,_skip_link:true,link_api_url:'https://api-sg.aliexpress.com/sync'}};
  }
  const productId=p.product_id||'';
  if(!productId) return {json:{...p,_skip_link:true,link_api_url:'https://api-sg.aliexpress.com/sync'}};
  return {json:{...p,_skip_link:false,link_api_url:buildShortLinkUrl(productId)}};
});

