const data = $json.data.boards[0];
const now = new Date();
const oneHourAgo = new Date(now.getTime() - 60*60*1000);

let openTasks = [];
let newTasks = [];
let groupStats = {};

data.groups.forEach(group => {
  // Skip Done group for open tasks
  if (group.title !== 'Done') {
    group.items_page.items.forEach(item => {
      openTasks.push({
        name: item.name,
        group: group.title
      });
    });
  }

  // Count for stats
  if (group.title !== 'Done') {
    groupStats[group.title] = group.items_page.items.length;
  }

  // Find new tasks (added in last hour)
  group.items_page.items.forEach(item => {
    const itemTime = new Date(item.created_at || item.updated_at);
    if (itemTime > oneHourAgo) {
      newTasks.push({
        name: item.name,
        group: group.title
      });
    }
  });
});

return [{
  json: {
    openTasksCount: openTasks.length,
    openTasks: openTasks,
    newTasksCount: newTasks.length,
    newTasks: newTasks,
    hasNew: newTasks.length > 0,
    groupStats: groupStats
  }
}];

