function daysFromToday(v) { const d=parseDate(v); if(!d) return null; const t=new Date(); t.setHours(0,0,0,0); return Math.round((d-t)/86400000); }
function itemUrl(item) { const boardId = cfg.mondayBoardId || getBoard()?.id || ""; return boardId ? `https://phenome-networks.monday.com/boards/${boardId}/pulses/${item.id}` : ""; }
