const items = (board.items_page?.items || []).filter(i => !["deleted", "archived"].includes(i.state));
const active = items.filter(isActive);
const overdue = [], dueToday = [], dueSoon = [], waiting = [], working = [], noDue = [];
for (const item of active) {
  const due = getDueDate(item);
  const diff = daysFromToday(due);
  const st = getStatus(item).toLowerCase();
  if (diff === null) noDue.push(item);
  else if (diff < 0) overdue.push(item);
  else if (diff === 0) dueToday.push(item);
  else if (diff <= 7) dueSoon.push(item);
  if (st.includes("waiting")) waiting.push(item);
  if (st.includes("working")) working.push(item);
}

