  msg += "3. Add notes to tasks that changed today.\n\n";
  priority = [...dueToday, ...waiting, ...overdue, ...working];
} else if (isEnd) {
  msg += "End-of-day wrap-up\n";
  msg += "1. Update tasks you touched today.\n";
  msg += "2. Close anything actually done.\n";
  msg += "3. Leave tomorrow's first task obvious.\n\n";
  priority = [...dueToday, ...overdue, ...working, ...waiting];
} else {
  priority = [...overdue, ...dueToday, ...dueSoon, ...waiting, ...working];
}

const uniquePriority = priority.filter((v, i, arr) => arr.findIndex(x => x.id === v.id) === i);

if (overdue.length) {
  msg += "Overdue\n";
