function clip(text) {
  text = String(text || "No message generated");
  if (text.length <= maxChars) return text;
  return text.slice(0, maxChars - 120) + "\n\n...truncated. Use /tasks for more details.";
}

function getBoard() {
  const boards = result?.data?.boards || [];
  if (cfg.mondayBoardId) return boards.find(b => String(b.id) === String(cfg.mondayBoardId)) || boards[0];
  return boards.find(b => (b.name || "").toLowerCase() === String(cfg.boardName || "").toLowerCase()) || boards[0];
}
function getItems(board) { return board?.items_page?.items || []; }
function getCol(item, colId) { return item?.column_values?.find(c => c.id === colId)?.text?.trim() || ""; }
function getStatus(item) { return getCol(item, statusColumnId) || "No status"; }
function getDueDate(item) { return getCol(item, dueDateColumnId); }
function isDone(item) {
  const s = getStatus(item).toLowerCase();
  return s === doneLabel || s === "done" || s === "completed";
}
function isActive(item) { return !["deleted", "archived"].includes(item.state) && !isDone(item); }
function parseDate(value) {
  if (!value) return null;
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) return null;
  d.setHours(0, 0, 0, 0);
  return d;
}
function daysFromToday(dateValue) {
  const d = parseDate(dateValue);
  if (!d) return null;
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  return Math.round((d - today) / 86400000);
}
function groupTitle(item) { return item?.group?.title || "No group"; }
function itemUrl(item) {
  const boardId = cfg.mondayBoardId || getBoard()?.id || "";
  return boardId ? `https://phenome-networks.monday.com/boards/${boardId}/pulses/${item.id}` : "";
}
function openButtons(items, labelPrefix = "Open") {
