  return rows;
}
function shortTaskLine(item, idx = null) {
  const due = getDueDate(item);
  const status = getStatus(item);
  const group = groupTitle(item);
  let line = `${idx ? idx + ". " : "• "}${item.name}\n`;
  line += `  ID: ${item.id} | ${status}`;
  if (due) line += ` | Due: ${due}`;
  if (group) line += ` | ${group}`;
  return line;
}
function categorize(items) {
  const active = items.filter(isActive);
  const done = items.filter(isDone);
  const overdue = [], dueToday = [], dueSoon = [], noDueDate = [], waiting = [], working = [];
  const byStatus = {};
  const byGroup = {};
  for (const item of items) {
    const status = getStatus(item);
    byStatus[status] = (byStatus[status] || 0) + 1;
    const group = groupTitle(item);
    byGroup[group] = (byGroup[group] || 0) + 1;

    if (!isActive(item)) continue;

    const due = getDueDate(item);
    const diff = daysFromToday(due);
    const s = status.toLowerCase();

    if (diff === null) noDueDate.push(item);
    else if (diff < 0) overdue.push(item);
    else if (diff === 0) dueToday.push(item);
    else if (diff <= 7) dueSoon.push(item);

    if (s.includes("waiting")) waiting.push(item);
    if (s.includes("working")) working.push(item);
  }
  return { active, done, overdue, dueToday, dueSoon, noDueDate, waiting, working, byStatus, byGroup };
}
