function tzParts(date, timeZone) {
  const fmt = new Intl.DateTimeFormat("en-US", {
    timeZone,
    weekday: "short",
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
    hourCycle: "h23"
  });
  const parts = Object.fromEntries(fmt.formatToParts(date).map(p => [p.type, p.value]));
  return { weekday: parts.weekday, hour: parts.hour, minute: parts.minute };
}

const tz = cfg.remindersTimezone || "Asia/Jerusalem";
const p = tzParts(new Date(), tz);
const weekdayMap = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };
const day = weekdayMap[p.weekday];
const currentTime = `${p.hour}:${p.minute}`;
const workdays = Array.isArray(cfg.reminderWorkdays) ? cfg.reminderWorkdays.map(Number) : [0,1,2,3,4];

if (!workdays.includes(day)) {
  return [{ json: { shouldSendReminder: false, reason: `Not a workday in ${tz}` } }];
}

const slots = (cfg.reminderSlots || []).filter(r => r.enabled && String(r.time) === currentTime);
if (!slots.length) {
  return [{ json: { shouldSendReminder: false, reason: `No enabled reminder at ${currentTime} ${tz}` } }];
}

const boardSelector = cfg.mondayBoardId ? `boards(ids: [${cfg.mondayBoardId}])` : `boards(limit: ${Number(cfg.maxBoards || 50)})`;
const query = `{
  ${boardSelector} {
