    name
    items_page(limit: ${Number(cfg.maxItems || 200)}) {
      items {
        id
        name
        state
        group { id title }
        column_values(ids: ["${cfg.statusColumnId}", "${cfg.dueDateColumnId}", "${cfg.personColumnId}"]) {
          id
          text
          type
        }
      }
    }
  }
}`;

return [{
  json: {
    shouldSendReminder: true,
    operation: "scheduled_reminder",
    chatId: String(cfg.reminderChatId || cfg.defaultChatId),
    reminderTime: currentTime,
    reminderNames: slots.map(s => s.name).join(", "),
    mondayQuery: query
  }
}];

