function normalizeProduct(p, keyword) {
  const price     = parseFloat(p.target_sale_price || p.target_original_price || p.sale_price || '0');
  const origPrice = parseFloat(p.target_original_price || p.original_price || '0');
  const discount  = origPrice > 0 && price > 0 && origPrice > price
    ? Math.round((1 - price / origPrice) * 100) : (p.discount ? parseInt(p.discount) : 0);
  let rawRating = parseFloat((p.evaluate_rate || '0').replace('%',''));
  const rating  = rawRating > 5 ? rawRating / 20 : rawRating;
  const orders  = parseInt(p.lastest_volume || p.total_orders || '0');
  return {
    title: (p.product_title || p.title || '').trim(),
    price, original_price: origPrice, discount, rating, orders,
    affiliate_link: (p.promotion_link || p.affiliate_link || '').trim(),
    image: (p.product_main_image_url || p.image_url || '').trim(),
    category: keyword, product_id: String(p.product_id || '')
  };
}

let allNormalized = [], apiCallCount = 0;

for (let idx = 0; idx < allResponses.length; idx++) {
  const data    = allResponses[idx].json;
  const keyword = (allRequests[idx] || allRequests[0]).json.keyword || 'unknown';
  apiCallCount++;
  if (data.error_response) {
    console.log('API error for "' + keyword + '": ' + (data.error_response.msg || 'unknown'));
    continue;
  }
  let products = [];
  try {
    const root = data.aliexpress_affiliate_product_query_response ||
                 data.aliexpress_affiliate_hotproduct_query_response || data;
    const result = (root.resp_result && root.resp_result.result) || root.result || root;
    products = (result.products && result.products.product) || [];
    if (!Array.isArray(products)) products = [products];
  } catch(e) { console.log('Parse error for "' + keyword + '": ' + e.message); continue; }
  if (!products.length) { console.log('0 products for: ' + keyword); continue; }
  const normalized = products.map(p => normalizeProduct(p, keyword)).filter(p => p.title && p.affiliate_link && p.price > 0);
  console.log('"' + keyword + '": ' + normalized.length + '/' + products.length);
  allNormalized.push(...normalized);
}

const seen = new Set();
const deduped = allNormalized.filter(p => {
  if (!p.product_id) return true;
  if (seen.has(p.product_id)) return false;
  seen.add(p.product_id); return true;
});

console.log('Pool: ' + deduped.length + ' unique products (' + apiCallCount + ' API calls)');
if (!deduped.length) return [{ json: { _flow_status: 'no_products', category: 'all' } }];
