function scoreProduct(p) {
  const rating = p.rating || 0, orders = p.orders || 0, discount = p.discount || 0, price = p.price || 0;
  const base  = (rating * 30) + (Math.log10(orders + 1) * 25) + (discount * 2) - (price * 0.08);
  const tLow  = (p.title || '').toLowerCase();
  const boost = boostKws.some(k => tLow.includes(k)) ? 15 : 0;
  return { ...p, score: base + boost, score_details: 'base:' + base.toFixed(1) + ' boost:' + boost };
}
const scored = all.map(item => item.json).map(scoreProduct).sort((a, b) => b.score - a.score);
console.log('Scored', scored.length, 'products. Top:', scored[0] ? scored[0].score.toFixed(1) + ' (' + scored[0].title.slice(0,40) + ')' : 'none');
return scored.map(p => ({ json: p }));

const all = $input.all();
const cfg = $('Config').first().json;
const n = Math.max(1, parseInt(cfg.products_per_run) || 1);
const fallbackMsg = cfg.fallback_message_no_products || 'ℹ️ לא נמצאו מוצרים מתאימים כרגע.';
const products = all.map(i => i.json);

if (products.length === 1 && products[0]._flow_status) {
  if (products[0]._flow_status === 'api_error') return [{ json: { message_type: 'ERROR', telegram_message: '❌ שגיאה בשליפת מוצרים' } }];
  return [{ json: { message_type: 'INFO', telegram_message: fallbackMsg } }];
}
if (!products.length) return [{ json: { message_type: 'INFO', telegram_message: fallbackMsg } }];

// ── MEMORY: skip already-sent products (30-day TTL) ─────────────────
const TTL_MS = 30 * 24 * 60 * 60 * 1000;
const nowMs = Date.now();
let seen = {};
try {
  const sd = $getWorkflowStaticData('global');
  if (!sd.seenProducts) sd.seenProducts = {};
  // Clean expired
  for (const id of Object.keys(sd.seenProducts)) {
    if (nowMs - sd.seenProducts[id] > TTL_MS) delete sd.seenProducts[id];
  }
  seen = sd.seenProducts;
} catch(e) { console.log('staticData unavailable: ' + e.message); }

const unseenProducts = products.filter(p => p.product_id && !seen[p.product_id]);
console.log('Memory: ' + Object.keys(seen).length + ' seen IDs | unseen: ' + unseenProducts.length + '/' + products.length);

// Use unseen first; fall back to full pool if not enough
const productPool = unseenProducts.length >= n ? unseenProducts : products;
if (unseenProducts.length < n && products.length > unseenProducts.length) {
  console.log('Not enough unseen — using full pool as fallback');
}

// ── TITLE DEDUPLICATION (within this run) ─────────────────────
function cleanTitle(t) {
  t = (t || '').replace(/[一-鿿㐀-䶿]+/g, '');
  t = t.replace(/\b(NEW|HOT|SALE|BEST|TOP|ORIGINAL)\b\s*/gi, '');
  t = t.replace(/\b20[2-3][0-9]\b\s*/g, '');
  t = t.replace(/\s{2,}/g, ' ').trim();
  return t.replace(/^[\s,\-]+|[\s,\-]+$/g, '');
}

const STOP_WORDS = new Set(['with','from','that','this','have','for','are','but','not','you','all','can','her','was','one','our','out','day','get','has','him','his','how','its','may','who','did','let','put','say','she','too','use','way','and','the','ing','per','pcs','set','bag','box','case','type','size','new','hot','1pc','2pc','3pc']);

function titleWords(t) {
  return (t || '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(w => w.length > 3 && !STOP_WORDS.has(w));
}
function isTooSimilar(a, b) {
  const wa = new Set(titleWords(a));
  return titleWords(b).filter(w => wa.has(w)).length >= 3;
}

// Shuffle top 15
const POOL_SIZE = Math.min(15, productPool.length);
const pool = productPool.slice(0, POOL_SIZE);
for (let i = pool.length - 1; i > 0; i--) {
  const j = Math.floor(Math.random() * (i + 1));
  [pool[i], pool[j]] = [pool[j], pool[i]];
}
const shuffled = [...pool, ...productPool.slice(POOL_SIZE)];

const selected = [], selectedTitles = [];
for (const p of shuffled) {
  if (selected.length >= n) break;
  if (!selectedTitles.some(t => isTooSimilar(t, p.title))) {
    selected.push(p); selectedTitles.push(p.title);
  }
}
// Fallback fill
if (selected.length < n) {
  for (const p of productPool) {
    if (selected.length >= n) break;
    if (!selected.includes(p)) selected.push(p);
  }
}

// ── MARK AS SEEN ────────────────────────────────────────
try {
  const sd = $getWorkflowStaticData('global');
  for (const p of selected) { if (p.product_id) sd.seenProducts[p.product_id] = nowMs; }
  console.log('Marked ' + selected.length + ' as seen. Total seen: ' + Object.keys(sd.seenProducts).length);
} catch(e) { console.log('Could not update staticData: ' + e.message); }

console.log('Selected ' + selected.length + ' unique products from ' + products.length + ' candidates');

const result = selected.map(p => ({
  json: { ...p, message_type: 'PRODUCT', cleaned_title: cleanTitle(p.title), total_candidates: products.length }
}));
if (selected.length < n) {
  result.push({ json: { message_type: 'INFO', telegram_message: 'ℹ️ נמצאו ' + selected.length + ' מוצרים מתוך ' + n + ' שביקשת.' } });
}
return result;

