function format1(p, cat, hook, cta) {
  var msg = hook + '\n\n';
  msg += '\u2728 ' + p.title + '\n\n';
  var bullets = (p.benefit_bullets || []).slice(0, 3);
  if (bullets.length) msg += bullets.map(function(b){return '\u2B50 ' + b;}).join('\n') + '\n\n';
  if (p.price > 0) {
    msg += '\uD83D\uDCB0 \u05DE\u05D7\u05D9\u05E8: $' + p.price.toFixed(2);
    if (p.original_price > p.price && p.discount >= 10)
      msg += '  ~~$' + p.original_price.toFixed(2) + '~~  \uD83C\uDFF7\uFE0F ' + p.discount + '% \u05D4\u05E0\u05D7\u05D4';
    msg += '\n';
  }
  var parts = [];
  if (p.rating >= 4.0) parts.push('\u2B50 ' + p.rating.toFixed(1));
  if (p.orders > 0) parts.push('\uD83D\uDCE6 ' + fmt(p.orders) + ' \u05D4\u05D6\u05DE\u05E0\u05D5\u05EA');
  if (parts.length) msg += parts.join('  |  ') + '\n';
  msg += '\n' + cta + '\n' + p.affiliate_link;
  return msg;
}

function format2(p, cat, hook, cta) {
  var msg = hook + '\n\n';
  msg += '\uD83D\uDCCC ' + p.title + '\n\n';
  if (p.price > 0) {
    msg += '\uD83D\uDCB8 \u05E8\u05E7 $' + p.price.toFixed(2);
    if (p.discount >= 10) msg += ' (' + p.discount + '% \u05D4\u05E0\u05D7\u05D4!)';
    msg += '\n\n';
  }
  var bullets = (p.benefit_bullets || []).slice(0, 3);
  if (bullets.length) msg += '\u05DC\u05DE\u05D4 \u05D6\u05D4 \u05DB\u05DC \u05DB\u05DA \u05D8\u05D5\u05D1?\n' + bullets.map(function(b){return '\u2022 ' + b;}).join('\n') + '\n\n';
  var proofParts = [];
  if (p.orders > 0) proofParts.push(fmt(p.orders) + ' \u05D0\u05E0\u05E9\u05D9\u05DD \u05DB\u05D1\u05E8 \u05E7\u05E0\u05D5');
  if (p.rating >= 4.0) proofParts.push('\u05E6\u05D9\u05D5\u05DF ' + p.rating.toFixed(1) + ' \u05DE\u05EA\u05D5\u05DA 5');
  if (proofParts.length) msg += '\uD83D\uDC65 ' + proofParts.join(' | ') + '\n\n';
  msg += cta + '\n' + p.affiliate_link;
  return msg;
}

function format3(p, cat, hook, cta) {
  var msg = hook + '\n\n';
  var statParts = [];
  if (p.rating >= 4.0) statParts.push(p.rating.toFixed(1) + '\u2B50');
  if (p.orders > 0) statParts.push(fmt(p.orders) + ' \u05D4\u05D6\u05DE\u05E0\u05D5\u05EA');
  if (p.discount >= 10) statParts.push(p.discount + '% \u05D4\u05E0\u05D7\u05D4');
  if (statParts.length) msg += statParts.join(' \u00B7 ') + '\n\n';
  msg += '\uD83C\uDFF7\uFE0F ' + p.title + '\n\n';
  if (p.price > 0) {
    msg += '\u05D4\u05DE\u05D7\u05D9\u05E8: $' + p.price.toFixed(2);
    if (p.original_price > p.price && p.discount >= 10) msg += ' (\u05D1\u05DE\u05E7\u05D5\u05DD $' + p.original_price.toFixed(2) + ')';
    msg += '\n\n';
  }
  var bullets = (p.benefit_bullets || []).slice(0, 2);
  if (bullets.length) msg += bullets.map(function(b){return '\u2713 ' + b;}).join('\n') + '\n\n';
  msg += cta + '\n' + p.affiliate_link;
  return msg;
}

function buildPost(p, idx) {
  var h = hashId(p.product_id || String(idx));
  var cat = detectCategory(p.title);
  var hook = HOOKS[h % HOOKS.length](cat);
  var cta = CTAS[(h >>> 4) % CTAS.length];
  var fmtN = (h >>> 8) % 3;
  if (fmtN === 0) return format1(p, cat, hook, cta);
  if (fmtN === 1) return format2(p, cat, hook, cta);
  return format3(p, cat, hook, cta);
}

return all.map(function(item, idx) {
  var p = item.json;
  if (p.message_type === 'INFO' || p.message_type === 'ERROR') return item;
  var title = cleanTitle(p.cleaned_title || p.title || '\u05DE\u05D5\u05E6\u05E8 \u05DE\u05D5\u05DE\u05DC\u05E5');
  var enriched = {
    title: title, price: p.price || 0, original_price: p.original_price || 0,
    discount: p.discount || 0, rating: p.rating || 0, orders: p.orders || 0,
    benefit_bullets: p.benefit_bullets || [], product_id: p.product_id || String(idx),
    affiliate_link: p.affiliate_link || '', image: p.image || '',
    message_type: p.message_type, score: p.score
  };
  var telegramMsg = buildPost(enriched, idx);
  return { json: Object.assign({}, p, { title: title, message_type: 'PRODUCT', telegram_message: telegramMsg }) };
});

