const all = $input.all();
const cfg = $('Config').first().json;
const appKey = cfg.aliexpress_app_key, appSecret = cfg.aliexpress_app_secret, trackingId = cfg.aliexpress_tracking_id || 'default';
function formatTimestamp() {
  const now = new Date(), pad = n => String(n).padStart(2,'0');
  return now.getUTCFullYear()+'-'+pad(now.getUTCMonth()+1)+'-'+pad(now.getUTCDate())+' '+pad(now.getUTCHours())+':'+pad(now.getUTCMinutes())+':'+pad(now.getUTCSeconds());
}
function buildShortLinkUrl(productId) {
  const sourceValue = 'https://www.aliexpress.com/item/' + productId + '.html';
  const params = { app_key: appKey, sign_method: 'md5', timestamp: formatTimestamp(), v: '2.0', method: 'aliexpress.affiliate.link.generate', source_values: sourceValue, promotion_link_type: '0', tracking_id: trackingId };
  const signString = Object.keys(params).sort().map(k => k + params[k]).join('');
  params.sign = md5(appSecret + signString + appSecret).toUpperCase();
  return 'https://api-sg.aliexpress.com/sync?' + Object.keys(params).map(k => encodeURIComponent(k)+'='+encodeURIComponent(params[k])).join('&');
}
return all.map(item => {
  const p = item.json;
  if (p.message_type === 'INFO' || p.message_type === 'ERROR' || p._flow_status)
    return { json: { ...p, _skip_link: true, link_api_url: 'https://api-sg.aliexpress.com/sync' } };
  const productId = p.product_id || '';
  if (!productId) return { json: { ...p, _skip_link: true, link_api_url: 'https://api-sg.aliexpress.com/sync' } };
  return { json: { ...p, _skip_link: false, link_api_url: buildShortLinkUrl(productId) } };
})

const all = $input.all();
const prev = $('Build Short Link Req').all();
return all.map((item, idx) => {
  const origData = (prev[idx] || { json: {} }).json;
  const { link_api_url, _skip_link, ...cleanOrig } = origData;
  if (_skip_link) return { json: { ...cleanOrig, short_url: cleanOrig.affiliate_link || '' } };
  let shortLink = '';
  try {
    const resp = item.json;
    const result = resp?.aliexpress_affiliate_link_generate_response?.resp_result?.result;
    const links = result?.promotion_links?.promotion_link;
    if (Array.isArray(links) && links.length > 0) shortLink = links[0].promotion_link || '';
    else if (links && links.promotion_link) shortLink = links.promotion_link || '';
  } catch(e) { console.log('Short link parse error:', e.message); }
  if (!shortLink) { console.log('No short link — using fallback'); shortLink = cleanOrig.affiliate_link || ''; }
  const longUrl = cleanOrig.affiliate_link || '';
  const msg = longUrl && shortLink !== longUrl ? (cleanOrig.telegram_message || '').split(longUrl).join(shortLink) : (cleanOrig.telegram_message || '');
  return { json: { ...cleanOrig, affiliate_link: shortLink, short_url: shortLink, telegram_message: msg } };
});

const all = $input.all();
const cfg = $('Config').first().json;
const chatId = String(cfg.telegram_chat_id);
const enableImage = cfg.enable_image_message !== 'false';
return all.map(item => {
  const p = item.json;
  if (p.message_type === 'INFO' || p.message_type === 'ERROR') {
    return { json: { ...p, tg_method: 'sendMessage', tg_body_json: JSON.stringify({ chat_id: chatId, text: (p.telegram_message || '').substring(0, 4096) }) } };
  }
  const imageUrl = enableImage ? (p.image || '').trim() : '';
  const message  = (p.telegram_message || '').substring(0, 4096);
  let tgMethod, tgBody;
  if (imageUrl) {
    const caption = message.length > 1024 ? message.substring(0, 1021) + '...' : message;
    tgMethod = 'sendPhoto'; tgBody = { chat_id: chatId, photo: imageUrl, caption };
  } else {
    tgMethod = 'sendMessage'; tgBody = { chat_id: chatId, text: message };
  }
  return { json: { ...p, tg_method: tgMethod, tg_body_json: JSON.stringify(tgBody) } };
});
